
CREATE TABLE IF NOT EXISTS forum_category_groups(slug TEXT PRIMARY KEY,title_en TEXT NOT NULL,title_el TEXT NOT NULL,sort_order INTEGER NOT NULL);

CREATE TABLE IF NOT EXISTS forum_category_group_map(category_slug TEXT PRIMARY KEY REFERENCES forum_categories(slug),group_slug TEXT NOT NULL REFERENCES forum_category_groups(slug));

CREATE INDEX IF NOT EXISTS forum_category_group_map_group ON forum_category_group_map(group_slug);

